<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';
require_once __DIR__ . '/../src/FiscalConfiguration.php';
require_once __DIR__ . '/../src/CompanyConfiguration.php';
require_once __DIR__ . '/layout.php';
$context = reforma_tributaria_require_access();
$fiscal = ['available' => false, 'message' => 'A conferência fiscal ainda não está disponível nesta base.'];
$companySummary = ['active' => 0, 'inactive' => 0, 'unconfigured' => 0];
if ($db = reforma_tributaria_connect()) { try { $fiscal = ReformaTributariaFiscalConfiguration::summary($db); foreach (ReformaTributariaCompanyConfiguration::listForUser($db, $context['user_id']) as $company) { $class = $company['status']['class']; $companySummary[$class === 'status--active' ? 'active' : ($class === 'status--inactive' ? 'inactive' : 'unconfigured')]++; } } finally { mysqli_close($db); } }
reforma_tributaria_page_start('Visão geral — Reforma Tributária', 'overview');
?>
